files.templates/customer-onboarding-coordinato:
{
  "schema_version": 1,
  "template_id": "customer-onboarding-coordinator",
  "template_version": 1,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm the Customer Success role",
      "instructions": "Confirm whether Customer Onboarding Coordinator is this Crew's primary role or a supporting capability. Preserve an existing Crew identity and record the named owner."
    },
    {
      "id": "skill",
      "title": "Verify the selected skill",
      "instructions": "Confirm skills/customer-onboarding-coordinator/SKILL.md exists and customer-onboarding-coordinator is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Set account and outcome scope",
      "instructions": "Confirm the customer/account, purchased scope, intended first result, owner, timeframe, and authorized source scope. Minimum input: Customer/account reference, purchased scope, desired first result, onboarding owner, target date, and an authorized handoff or export."
    },
    {
      "id": "access",
      "title": "Test source access",
      "instructions": "Read one representative authorized source or export. CRM or signed deal handoff, onboarding tracker, product workspace, and approved customer inbox; a supplied handoff file is enough for the first plan. Record exact account, date coverage, and missing access; a named provider is not a connected account."
    },
    {
      "id": "definitions",
      "title": "Agree on evidence and action rules",
      "instructions": "Confirm milestone or metric definitions, identity mapping, source coverage, owner, customer contact policy, and what counts as observed completion. Mark unresolved definitions as blockers."
    },
    {
      "id": "first_result",
      "title": "Produce the first result",
      "instructions": "Produce An onboarding milestone register with owners, evidence, blockers, and the next customer decision. Every completion and blocker cites a source and observation time; unobserved milestones remain pending or unknown. Use actual authorized data; a fictional example alone does not complete this check."
    },
    {
      "id": "review",
      "title": "Review the first result",
      "instructions": "Show a representative result to the owner and record corrections, decision, and next action before completing setup."
    },
    {
      "id": "delivery",
      "title": "Decide on delivery",
      "optional": true,
      "instructions": "Choose chat-only or a separately authorized customer/CRM delivery route. Chat-only completes this decision. A draft, reminder, or health brief is not permission to message a customer or mutate an account."
    },
    {
      "id": "recurrence",
      "title": "Decide on recurrence",
      "optional": true,
      "instructions": "Choose manual-only or a separately reviewed schedule, authenticated trigger, callable function, or Automation. Manual-only completes this decision; test any configured route before activation."
    }
  ],
  "completed_steps": []
}

